css:
.row {
  display: flex;
  align-items: baseline; /* align the text, not the boxes */
  gap: 8px;
  padding: 12px;
  border: 2px dashed #a1a1aa;
}

.label {
  font-size: 12px;
  color: #52525b;
  text-transform: uppercase;
}

.value {
  font-size: 32px;
  font-weight: 700;
}

.unit {
  font-size: 14px;
}
